async function groceryMenuOverview(){const pages=[['Overview','grocery_overview','◫','Store activity and key figures'],['Products & stock','grocery_products','▦','Products, barcodes and inventory'],['Sales','grocery_sales','↗','Create and review customer sales'],['Recent Sales','grocery_recent_sales','◷','Browse and print saved sales bills'],['Purchases','grocery_purchases','＋','Receive stock from suppliers'],['Customers','grocery_customers','♙','Customer records and balances'],['Suppliers','grocery_suppliers','▣','Supplier directory'],['Customer Wallet','grocery_customer_wallet','¤','Credit bills and received payments'],['Supplier Wallet','grocery_supplier_wallet','⇄','Supplier bills and payments'],['Day book','grocery_daybook','▤','Sales, purchases and account activity'],['Expenses','grocery_expenses','−','Record and review shop expenses'],['Reports','grocery_reports','▥','Sales, VAT and stock reports']];const cards=pages.map(p=>'<button type="button" class="grocery-shortcut" data-go="'+p[1]+'"><span class="grocery-shortcut-icon">'+p[2]+'</span><span><b>'+esc(p[0])+'</b><small>'+esc(p[3])+'</small></span><span class="grocery-shortcut-arrow">→</span></button>').join('');$('#content').innerHTML=gh('GROCERY · MENU','Menu Overview','Open any Grocery workspace directly.')+'<div class="grocery-shortcut-grid">'+cards+'</div>'}
